import {dayKey,plusDays,makePlan,demoState,validateState} from './planner.mjs';
const $=id=>document.getElementById(id), KEY='rebound-plan-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=demoState(),selected=0,plan,undoState=null,toastTimeout,storageFailed=false,confirmCallback;
try {const saved=localStorage.getItem(KEY);if(saved)state=validateState(JSON.parse(saved));}catch{storageFailed=true;}
if(state.budgetDate!==dayKey()){state.budgetDate=dayKey();state.todayBudget=state.budget;}
const dateLabel=(key,opts={month:'short',day:'numeric'})=>new Date(key+'T12:00:00').toLocaleDateString(undefined,opts);
function notify(message,undo=false){clearTimeout(toastTimeout);$('status').innerHTML=esc(message)+(undo?' <button id="undoButton">Undo</button>':'');$('status').hidden=false;if(undo)$('undoButton').onclick=()=>{if(undoState){state=undoState;undoState=null;save();render();notify('Change undone.');}};toastTimeout=setTimeout(()=>$('status').hidden=true,9000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;}$('storageStatus').textContent=storageFailed?'Storage unavailable — save a backup':'Saved on this device';}
function mutate(action,message){undoState=structuredClone(state);action();save();render();if(message)notify(message,true);}
function sessionHTML(s,i,dayIndex){return `<article class="session"><button class="complete" data-complete="${dayIndex}:${i}" aria-label="Complete ${s.minutes} minutes of ${esc(s.title)}" ${dayIndex!==0?'disabled title="Complete sessions on the day they are scheduled"':''}>✓</button><div><p class="session-title">${esc(s.title)}</p><div class="session-meta"><span class="subject">${esc(s.subject)}</span><span>Due ${dateLabel(s.due)}${s.due<dayKey()?' · overdue':''}</span></div></div><button class="quiet focus-session" data-focus="${dayIndex}:${i}" ${dayIndex!==0?'disabled':''}>Focus</button><div class="session-time">${s.minutes}<small>MINUTES</small></div></article>`;}
function renderDay(){const day=plan.days[selected];$('dayTitle').textContent=selected===0?'Today’s small steps':dateLabel(day.date,{weekday:'long',month:'short',day:'numeric'});$('dayTotal').textContent=`${day.used} / ${day.capacity} min`; $('sessions').innerHTML=day.sessions.map((s,i)=>sessionHTML(s,i,selected)).join('') || `<div class="empty"><strong>${!state.tasks.length?'A fresh page. A fresh start.':day.capacity===0?'Room to rest.':selected===0?'You have breathing room.':'Nothing scheduled here.'}</strong>${!state.tasks.length?'Add your first assignment to build a plan.':day.capacity===0?'No sessions today. Your unfinished work stays in the plan.':'Check your assignments and any deadlines that need attention.'}</div>`;document.querySelectorAll('.day').forEach((b,i)=>{b.classList.toggle('active',i===selected);b.setAttribute('aria-pressed',String(i===selected));});}
function render(){plan=makePlan(state);$('demoBanner').hidden=!state.demo;$('taskCount').textContent=state.tasks.length;$('todayBudget').max=Math.max(180,state.todayBudget);$('todayBudget').value=state.todayBudget;$('budgetOutput').value=state.todayBudget;
 if(![...$('dailyBudget').options].some(o=>Number(o.value)===state.budget)){const o=new Option(`${state.budget} minutes`,String(state.budget));$('dailyBudget').add(o);}$('dailyBudget').value=state.budget;
 $('dateLabel').textContent=`${dateLabel(plan.days[0].date)} – ${dateLabel(plan.days[6].date)} · YOUR NEXT SEVEN DAYS`;
 const completed=state.tasks.reduce((sum,t)=>sum+t.done,0),blocked=plan.risks.filter(r=>!r.beyondHorizon);
 $('stats').innerHTML=`<div class="stat"><strong>${plan.scheduled}<small>min</small></strong><span>planned this week</span></div><div class="stat"><strong>${completed}<small>min</small></strong><span>completed so far</span></div><div class="stat"><strong>${blocked.length}<small>${blocked.length===1?'deadline':'deadlines'}</small></strong><span>need attention</span></div>`;
 $('riskPanel').innerHTML=plan.risks.length?`<div class="risk"><span class="risk-icon" aria-hidden="true">!</span><div><strong>${blocked.length?'You don’t have to squeeze everything in.':'Some work belongs in a later week.'}</strong><p>${plan.risks.map(r=>`${esc(r.subject)}: ${r.overdue?'past due'+(r.minutes?`, ${r.minutes} min won’t fit today`:'; planned today'):r.beyondHorizon?`${r.minutes} min beyond this week`:`${r.minutes} min won’t fit before ${dateLabel(r.due)}`}`).join(' · ')}</p></div>${blocked.length?'<button id="teacherButton" class="quiet">Ask for more time</button>':''}</div>`:'';
 if($('teacherButton'))$('teacherButton').onclick=openTeacher;
 $('week').innerHTML=plan.days.map((d,i)=>`<button class="day ${i===selected?'active':''}" data-day="${i}" aria-pressed="${i===selected}" aria-label="${dateLabel(d.date,{weekday:'long',month:'long',day:'numeric'})}, ${d.used} of ${d.capacity} minutes"><span class="day-name">${i===0?'TODAY':dateLabel(d.date,{weekday:'short'}).toUpperCase()}</span><span class="day-date">${new Date(d.date+'T12:00:00').getDate()}</span><span class="load-track" aria-hidden="true"><i style="width:${d.capacity?d.used/d.capacity*100:0}%"></i></span><span class="day-min">${d.used} min</span></button>`).join('');renderDay();
 $('assignments').innerHTML=state.tasks.length?state.tasks.map(t=>`<article class="assignment"><div class="assignment-info"><h3>${esc(t.title)}</h3><p>${esc(t.subject)} · Due ${dateLabel(t.due)} · ${t.done} / ${t.minutes} min completed${t.priority==='high'?' · High priority':''}</p><div class="progress" role="progressbar" aria-label="${esc(t.title)} completion" aria-valuemin="0" aria-valuemax="${t.minutes}" aria-valuenow="${t.done}"><i style="width:${t.done/t.minutes*100}%"></i></div></div>${t.done===t.minutes?'<span class="done-label">✓ Done</span>':''}<div class="assignment-buttons"><button class="quiet" data-edit="${esc(t.id)}">Edit</button>${t.done?`<button class="quiet" data-reset="${esc(t.id)}">Reset progress</button>`:''}<button class="quiet" data-delete="${esc(t.id)}">Remove</button></div></article>`).join(''):'<div class="empty"><strong>No assignments yet.</strong>Add one above. A rough time estimate is enough to start.</div>';
 $('storageStatus').textContent=storageFailed?'Storage unavailable — save a backup':'Saved on this device';}
function openTask(id){$('taskForm').reset();$('formError').textContent='';$('taskId').value=id||'';$('taskDialogTitle').textContent=id?'Edit assignment':'Add an assignment';$('due').value=plusDays(dayKey(),1);if(id){const t=state.tasks.find(t=>t.id===id);for(const key of ['title','subject','due','minutes','priority'])$(key).value=t[key];}$('taskDialog').showModal();$('title').focus();}
function switchTab(which){for(const p of ['plan','work']){$(p+'Panel').hidden=p!==which;$(p+'Tab').setAttribute('aria-selected',String(p===which));$(p+'Tab').tabIndex=p===which?0:-1;}}
function confirmAction(title,text,callback){$('confirmTitle').textContent=title;$('confirmText').textContent=text;confirmCallback=callback;$('confirmDialog').showModal();}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openTeacher(){const risks=plan.risks.filter(r=>!r.beyondHorizon);$('teacherDraft').value=`Hi,\n\nI’m catching up on missed schoolwork and have made a plan for the time I have available. I need help with:\n\n${risks.map(r=>`• ${r.title} (${r.subject}), due ${dateLabel(r.due)}: ${r.overdue?'already overdue':`${r.minutes} minutes do not fit before the deadline`}.`).join('\n')}\n\nCould we agree on a realistic new deadline, or decide which parts to do first? I can share my catch-up plan.\n\nThank you.`;$('teacherDialog').showModal();}
$('addButton').onclick=()=>openTask();$('aboutButton').onclick=()=>$('helpDialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('planTab').onclick=()=>switchTab('plan');$('workTab').onclick=()=>switchTab('work');document.querySelector('.tabs').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const which=e.key==='Home'?'plan':e.key==='End'?'work':$('planPanel').hidden?'plan':'work';switchTab(which);$(which+'Tab').focus();}};
$('todayBudget').oninput=()=>{state.todayBudget=Number($('todayBudget').value);state.budgetDate=dayKey();save();render();};$('dailyBudget').onchange=()=>{state.budget=Number($('dailyBudget').value);save();render();notify('Plan updated to fit your time.');};
$('week').onclick=e=>{const b=e.target.closest('[data-day]');if(b){selected=Number(b.dataset.day);renderDay();}};
$('sessions').onclick=e=>{const f=e.target.closest('[data-focus]');if(f){const [d,i]=f.dataset.focus.split(':').map(Number);if(d===0)window.dispatchEvent(new CustomEvent('rebound:focus',{detail:{...plan.days[d].sessions[i]}}));return;}const b=e.target.closest('[data-complete]');if(!b)return;const [d,i]=b.dataset.complete.split(':').map(Number);if(d!==0)return;const s=plan.days[d].sessions[i];mutate(()=>{state.tasks.find(t=>t.id===s.taskId).done+=s.minutes;state.todayBudget=Math.max(0,state.todayBudget-s.minutes);},`${s.minutes} minutes done. Today’s remaining time adjusted.`);};
$('taskForm').onsubmit=e=>{e.preventDefault();try{const id=$('taskId').value,old=state.tasks.find(t=>t.id===id),t={id:id||crypto.randomUUID(),title:$('title').value.trim(),subject:$('subject').value.trim(),due:$('due').value,minutes:Number($('minutes').value),done:old?.done||0,priority:$('priority').value};if(t.done>t.minutes)throw new Error(`Total time must be at least the ${t.done} minutes already completed.`);if(!t.title||!t.subject)throw new Error('Please enter an assignment and subject.');validateState({...state,tasks:id?state.tasks.map(x=>x.id===id?t:x):[...state.tasks,t]});mutate(()=>{state.tasks=id?state.tasks.map(x=>x.id===id?t:x):[...state.tasks,t];},'Assignment saved. Your plan is ready.');$('taskDialog').close();}catch(err){$('formError').textContent=err.message;}};
$('assignments').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)openTask(b.dataset.edit);if(b.dataset.delete)mutate(()=>{state.tasks=state.tasks.filter(t=>t.id!==b.dataset.delete);},'Assignment removed.');if(b.dataset.reset)mutate(()=>{state.tasks.find(t=>t.id===b.dataset.reset).done=0;},'Progress reset. Adjust today’s study time if needed.');};
$('confirmAction').onclick=()=>{$('confirmDialog').close();confirmCallback?.();};
$('startOwn').onclick=()=>confirmAction('Start your own plan?','This replaces the sample and any changes to it. Save a backup first if you want to keep them.',()=>{mutate(()=>{state={version:1,tasks:[],budget:60,todayBudget:45,budgetDate:dayKey(),demo:false};selected=0;},'Your fresh plan is ready.');openTask();});
$('demoButton').onclick=()=>confirmAction('Load a sample week?','This replaces your current assignments. Save a backup first if you want to keep them.',()=>{mutate(()=>{state=demoState();selected=0;},'Fictional sample week loaded.');switchTab('plan');});
$('exportButton').onclick=()=>{download(`rebound-backup-${dayKey()}.json`,JSON.stringify(state,null,2),'application/json');notify('Backup downloaded. Keep it somewhere safe.');};$('importButton').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{const file=$('importFile').files[0];if(!file)return;try{if(file.size>250000)throw new Error('Choose a Rebound backup smaller than 250 KB.');const incoming=validateState(JSON.parse(await file.text()));confirmAction('Restore this backup?',`Replace your current plan with ${incoming.tasks.length} assignments? Save your current plan first if needed.`,()=>{mutate(()=>{state=incoming;if(state.budgetDate!==dayKey()){state.budgetDate=dayKey();state.todayBudget=state.budget;}selected=0;},'Backup restored.');});}catch(e){notify(e.message||'Could not read backup.');}$('importFile').value='';};
$('copyDraft').onclick=async()=>{try{await navigator.clipboard.writeText($('teacherDraft').value);notify('Draft copied. Review it before sending.');}catch{$('teacherDraft').select();notify('Select and copy the draft using your keyboard.');}};
$('printButton').onclick=()=>{switchTab('plan');window.print();};window.addEventListener('beforeprint',()=>{$('sessions').innerHTML=plan.days.map((d,i)=>`<h3 class="print-day">${dateLabel(d.date,{weekday:'long',month:'short',day:'numeric'})} · ${d.used}/${d.capacity} min</h3>${d.sessions.map((s,j)=>sessionHTML(s,j,i)).join('')||'<p>No sessions scheduled.</p>'}`).join('');});window.addEventListener('afterprint',renderDay);
window.addEventListener('storage',e=>{if(e.key===KEY)notify('This plan changed in another tab. Reload before making more changes.');});
window.addEventListener('focus',()=>{if(state.budgetDate!==dayKey()){state.budgetDate=dayKey();state.todayBudget=state.budget;selected=0;save();render();}});
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_catch_up_plan',title:'Read catch-up plan',description:'Read the current device-local seven-day catch-up plan and deadlines needing attention. Does not change assignments.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');return makePlan(state);}})).catch(()=>{});}catch{}}

window.addEventListener('rebound:credit',e=>{const {sessionId,taskId,minutes}=e.detail;let credits;try{credits=JSON.parse(localStorage.getItem('rebound-focus-credits')||'[]');}catch{credits=[];}if(credits.includes(sessionId))return;const task=state.tasks.find(t=>t.id===taskId);if(!task||!Number.isInteger(minutes)||minutes<1)return;const credit=Math.min(minutes,task.minutes-task.done);mutate(()=>{task.done+=credit;state.todayBudget=Math.max(0,state.todayBudget-credit);},'Focus session added to your catch-up progress.');credits.push(sessionId);try{localStorage.setItem('rebound-focus-credits',JSON.stringify(credits.slice(-500)));}catch{}});
